definition.script:
// Lorem Ipsum Generator

var count = parseInt(input.get("count") || "3");
var unit = input.get("unit") || "paragraphs";
var startWithLorem = input.get("startWithLorem") !== "false";

// Lorem ipsum word bank
var words = [
    "lorem", "ipsum", "dolor", "sit", "amet", "consectetur", "adipiscing", "elit",
    "sed", "do", "eiusmod", "tempor", "incididunt", "ut", "labore", "et", "dolore",
    "magna", "aliqua", "enim", "ad", "minim", "veniam", "quis", "nostrud",
    "exercitation", "ullamco", "laboris", "nisi", "aliquip", "ex", "ea", "commodo",
    "consequat", "duis", "aute", "irure", "in", "reprehenderit", "voluptate",
    "velit", "esse", "cillum", "fugiat", "nulla", "pariatur", "excepteur", "sint",
    "occaecat", "cupidatat", "non", "proident", "sunt", "culpa", "qui", "officia",
    "deserunt", "mollit", "anim", "id", "est", "laborum", "perspiciatis", "unde",
    "omnis", "iste", "natus", "error", "voluptatem", "accusantium", "doloremque",
    "laudantium", "totam", "rem", "aperiam", "eaque", "ipsa", "quae", "ab", "illo",
    "inventore", "veritatis", "quasi", "architecto", "beatae", "vitae", "dicta",
    "explicabo", "nemo", "ipsam", "quia", "voluptas", "aspernatur", "aut", "odit",
    "fugit", "consequuntur", "magni", "dolores", "eos", "ratione", "sequi",
    "nesciunt", "neque", "porro", "quisquam", "numquam", "eius", "modi", "tempora",
    "incidunt", "magnam", "quaerat", "minima", "nostrum", "exercitationem",
    "ullam", "corporis", "suscipit", "laboriosam", "aliquid", "commodi"
];

var firstSentence = "Lorem ipsum dolor sit amet, consectetur adipiscing elit.";

function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function capitalize(str) {
    return str.charAt(0).toUpperCase() + str.slice(1);
}

function generateWord() {
    return words[randomInt(0, words.length - 1)];
}

function generateSentence(wordCount) {
    var count = wordCount || randomInt(8, 15);
    var sentence = [];
    for (var i = 0; i < count; i++) {
        sentence.push(generateWord());
    }
    return capitalize(sentence.join(' ')) + '.';
}

function generateParagraph(sentenceCount) {
    var count = sentenceCount || randomInt(4, 8);
    var sentences = [];
    for (var i = 0; i < count; i++) {
        sentences.push(generateSentence());
    }
    return sentences.join(' ');
}

try {
    var result = "";
    var wordCount = 0;
    var sentenceCount = 0;
    var paragraphCount = 0;

    if (unit === "words") {
        var wordList = [];
        if (startWithLorem) {
            wordList = ["Lorem", "ipsum"];
            for (var i = 2; i < count; i++) {
                wordList.push(generateWord());
            }
        } else {
            for (var i = 0; i < count; i++) {
                wordList.push(generateWord());
            }
        }
        result = wordList.join(' ');
        wordCount = count;
    } else if (unit === "sentences") {
        var sentences = [];
        for (var i = 0; i < count; i++) {
            if (i === 0 && startWithLorem) {
                sentences.push(firstSentence);
            } else {
                sentences.push(generateSentence());
            }
        }
        result = sentences.join(' ');
        sentenceCount = count;
        wordCount = result.split(/\s+/).length;
    } else {
        // paragraphs
        var paragraphs = [];
        for (var i = 0; i < count; i++) {
            if (i === 0 && startWithLorem) {
                paragraphs.push(firstSentence + ' ' + generateParagraph(randomInt(3, 6)));
            } else {
                paragraphs.push(generateParagraph());
            }
        }
        result = paragraphs.join('\n\n');
        paragraphCount = count;
        sentenceCount = result.split(/[.!?]+/).length - 1;
        wordCount = result.split(/\s+/).length;
    }

    output.set("Text", result);
    output.set("WordCount", wordCount);
    output.set("SentenceCount", sentenceCount);
    output.set("ParagraphCount", paragraphCount);
    output.set("CharacterCount", result.length);
    output.set("HasErrors", false);
    output.set("ErrorMessage", "");

    log.info("Generated " + count + " " + unit + " (" + wordCount + " words)");
    tags.trigger("success");

} catch (ex) {
    log.error("Generation failed: " + ex.message);
    output.set("HasErrors", true);
    output.set("ErrorMessage", ex.message);
    output.set("Text", "");
    tags.trigger("error");
}
